func:
// Builds the Provideam proof request settings for one report day.
// In: manual trigger. Out: msg.proof with the API key, URL and the
// New Plan OPT report body (docs/provideam-samples/23) for DAY.
var PROVIDEAM_API_KEY = 'PASTE_PROVIDEAM_API_KEY_HERE';
var REPORT_NAME = 'New Plan OPT Report';
// Production day YYYY-MM-DD. Empty = yesterday (UTC date).
var DAY = '';
var PROVIDEAM_URL = 'https://rb-api.provideam.com';
PROVIDEAM_URL += '/api/v1/Report/ObjectByPeriod';
// Machine IDs of the saved report (Hull lines).
var MACHINE_IDS = '297,164,165,59,65,57,58,167,166,269,270,209,210,154,';
MACHINE_IDS += '317,295,63,207,221,60,64,169,61,213,214,211,24,206,30,';
MACHINE_IDS += '31,203,202,42,69,68,218,216,212,38,39,40,200,222,275,';
MACHINE_IDS += '249,215,43';
var FIELDS = [
  'fdYYYYMMDD',
  'fdAreaName',
  'fdMachineName',
  'fdShiftName',
  'fdShiftStartTime',
  'fdPartName'
];
// Function name and its column index in the saved report.
var FUNCTIONS = [
  ['fnGoodParts', 2],
  ['fnDefectParts', 4],
  ['fnTarget', 6],
  ['fnCapacity', 8],
  ['fnOEE', 10],
  ['fnTotalTime', 12],
  ['fnPlannedOpT', 13],
  ['fnOEETime', 14],
  ['fnDowntimeUnits', 15]
];

if (PROVIDEAM_API_KEY.indexOf('PASTE_') === 0) {
  msg.proofFailureReason = 'Fill in PROVIDEAM_API_KEY';
  node.error(msg.proofFailureReason, msg);
  return null;
}

var day = DAY;
if (!day) {
  var d = new Date(Date.now() - 86400000);
  day = d.toISOString().slice(0, 10);
}
if (!/^\d{4}-\d\d-\d\d$/.test(day)) {
  msg.proofFailureReason = 'DAY must be YYYY-MM-DD';
  node.error(msg.proofFailureReason, msg);
  return null;
}

var body = {
  userId: 2908,
  formattedJson: false,
  applyStdTimeCorrection: true,
  includeGrandTotals: true,
  objects: [
    {
      objectParam: {
        obMachineID: MACHINE_IDS.split(',')
      }
    }
  ],
  fields: FIELDS.map(function (name) {
    return { fieldName: name };
  }),
  functions: FUNCTIONS.map(function (f) {
    return { funcName: f[0], index: f[1] };
  }),
  periods: [
    {
      periodParam: {
        pdDay: ['[' + day + 'T00:00:00]']
      }
    }
  ]
};

msg.proof = {
  apiKey: PROVIDEAM_API_KEY,
  url: PROVIDEAM_URL,
  body: body,
  report: REPORT_NAME,
  day: day
};
msg.proofFile = {
  name: REPORT_NAME + ' ' + day
};
msg._proofStage = 'settings';
node.status({ fill: 'green', shape: 'dot', text: 'settings ready' });
return msg;

// Builds the Provideam report request (read-style POST).
// In: proof settings. Out: an HTTP request for one report day.
// Provideam answers HTTP 500 to a body with more than 18 functions.
msg.method = 'POST';
msg.url = msg.proof.url;
msg.headers = {
  'apiKey': msg.proof.apiKey,
  'Content-Type': 'application/json-patch+json',
  'Accept': 'application/json'
};
msg.payload = JSON.stringify(msg.proof.body);
msg._proofStage = 'Provideam report';
node.status({ fill: 'blue', shape: 'dot', text: 'calling Provideam' });
return msg;

// Checks the Provideam response and shows the report rows.
// In: report response as text. Out: msg.payload with the report name,
// day, row count and the rows (processedData) for the debug sidebar.
if (msg.statusCode !== 200) {
  msg.proofFailureReason = 'Provideam HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

var rows;
try {
  rows = JSON.parse(String(msg.payload || '')).processedData;
} catch (e) {
  msg.proofFailureReason = 'Provideam response is not JSON';
  node.error(msg.proofFailureReason, msg);
  return null;
}
if (!Array.isArray(rows)) {
  msg.proofFailureReason = 'Provideam response has no processedData';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.payload = {
  report: msg.proof.report,
  day: msg.proof.day,
  rowCount: rows.length,
  rows: rows
};
delete msg.proof;
delete msg.headers;
delete msg.url;
delete msg.method;
delete msg._proofStage;
node.status({
  fill: 'green',
  shape: 'dot',
  text: rows.length + ' rows from Provideam'
});
return msg;

// Reports a sanitized proof failure.
// In: a caught error. Out: a short debug message without request details.
var stage = msg._proofStage || 'proof';
var reason = msg.proofFailureReason || 'request failed';
var name = msg.proofFile && msg.proofFile.name;
var text = 'FAILED ' + stage;

if (name) {
  text += ' ' + name;
}
text += ': ' + reason;
msg.payload = text;
delete msg.proof;
delete msg.lakeToken;
delete msg.signedUrl;
delete msg.url;
delete msg.headers;
delete msg.method;
delete msg.fileBytes;
delete msg._proofStage;
delete msg.proofFailureReason;
node.status({ fill: 'red', shape: 'ring', text: 'proof failed' });
return msg;
